+using Microsoft.ML;
+using TicketClassifier.Models;
+
+namespace TicketClassifier.Services;
+
+public class ModelTrainingService
+{
+    private readonly string _dataPath;
+    private readonly string _modelPath;
+    private readonly ILogger<ModelTrainingService> _logger;
+
+    public ModelTrainingService(IConfiguration configuration, ILogger<ModelTrainingService> logger)
+    {
+        _dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
+        _modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
+        _logger = logger;
+    }
+
+    public void TrainAndSaveModel()
+    {
+        var mlContext = new MLContext(seed: 42);
+
+        IDataView dataView = mlContext.Data.LoadFromTextFile<TicketData>(
+            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
+
+        var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2, seed: 42);
+
+        // Featurize text columns and combine with Priority
+        var pipeline = mlContext.Transforms.Conversion
+            .MapValueToKey("Label", nameof(TicketData.Category))
+            .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
+            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
+            .Append(mlContext.Transforms.Concatenate("Features",
+                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
+            .Append(mlContext.MulticlassClassification.Trainers
+                .SdcaMaximumEntropy("Label", "Features"))
+            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
+
+        _logger.LogInformation("Training model with {TrainRows} training rows...",
+            mlContext.Data.CreateEnumerable<TicketData>(split.TrainSet, reuseRowObject: false).Count());
+
+        ITransformer model = pipeline.Fit(split.TrainSet);
+
+        // Evaluate on the test set
+        var predictions = model.Transform(split.TestSet);
+        var metrics = mlContext.MulticlassClassification.Evaluate(predictions, "Label");
+
+        _logger.LogInformation("=== Model Evaluation Metrics ===");
+        _logger.LogInformation("Macro Accuracy:    {MacroAccuracy:F4}", metrics.MacroAccuracy);
+        _logger.LogInformation("Micro Accuracy:    {MicroAccuracy:F4}", metrics.MicroAccuracy);
+        _logger.LogInformation("Log Loss:          {LogLoss:F4}", metrics.LogLoss);
+        _logger.LogInformation("Log Loss Reduction:{LogLossReduction:F4}", metrics.LogLossReduction);
+
+        foreach (var classMetric in metrics.PerClassLogLoss)
+        {
+            _logger.LogInformation("Per-Class Log Loss: {ClassLogLoss:F4}", classMetric);
+        }
+
+        mlContext.Model.Save(model, split.TrainSet.Schema, _modelPath);
+        _logger.LogInformation("Model saved to {ModelPath}", _modelPath);
+    }
+
+    public string GetModelPath() => _modelPath;
+}
+

