using Microsoft.Extensions.ML;
using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup so the .zip file exists before the pool needs it
var trainer = new ModelTrainingService(builder.Configuration,
    LoggerFactory.Create(b => b.AddConsole()).CreateLogger<ModelTrainingService>());
trainer.TrainAndSaveModel();

// Extract score label names from the trained model
var mlContext = new MLContext();
var model = mlContext.Model.Load(trainer.GetModelPath(), out var schema);
var outputSchema = model.GetOutputSchema(schema);
var scoreColumn = outputSchema["Score"];
var slotNames = new VBuffer<ReadOnlyMemory<char>>();
scoreColumn.GetSlotNames(ref slotNames);
var labelNames = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
builder.Services.AddSingleton(new ScoreLabelNames(labelNames));

builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(trainer.GetModelPath());

var app = builder.Build();
app.MapControllers();
app.Run();

